/**
 * RPC stubs of the server's `encryption` actions (server/src/actions/encryption.rs):
 * per-account file encryption, docs/ENCRYPTION.md. Not upstream, so not
 * generated by scripts/gen-actions.mjs; written the same way.
 *
 * Every failure comes back as data (`{ ok: false, reason }`), never as a thrown
 * error, and no answer ever carries the file password.
 */
import { callAction } from "../runtime/rpc";

export type VaultState = "off" | "encrypting" | "on" | "decrypting";
export type VaultGrantKind = "owner" | "visitor" | "app";

/** One browser or app that remembers the file password. */
export interface VaultGrantView {
  id: string;
  kind: VaultGrantKind;
  /** "Chrome 141 · macOS"; attacker-controlled text, render as text only. */
  label: string | null;
  ip: string | null;
  createdAt: string;
  lastUsedAt: string | null;
  expiresAt: string;
  /** The grant this browser holds. */
  current: boolean;
}

/** The Settings card (server/src/vault/status.rs `VaultStatus`). */
export interface VaultStatus {
  state: VaultState;
  /** This browser holds a live grant. */
  unlocked: boolean;
  progress: { done: number; total: number };
  /** The background pass could not finish some files yet (it retries). */
  error: boolean;
  since: string | null;
  grants: VaultGrantView[];
  minLength: number;
}

export type VaultReason =
  | "wrong"
  | "rate-limited"
  | "mismatch"
  | "too-short"
  | "too-long"
  | "same-as-sign-in"
  | "not-acknowledged"
  | "already-on"
  | "busy"
  | "not-encrypted"
  | "not-found";

export type VaultResult = { ok: true } | { ok: false; reason: VaultReason; retryAfter?: number };

/** Whose files an unlock page is for. */
export type UnlockTarget = { mediaId: string } | { tag: string } | { path: string };

export async function loadEncryptionStatus(): Promise<VaultStatus> {
  return callAction("encryption", "loadEncryptionStatus", arguments);
}

/** Switch encryption on; this browser is unlocked right away. */
export async function enableEncryption(
  password: string,
  confirm: string,
  acknowledged: boolean,
): Promise<VaultResult> {
  return callAction("encryption", "enableEncryption", arguments);
}

/** Unlock the caller's own files on this browser. */
export async function unlockMyFiles(password: string, remember: boolean): Promise<VaultResult> {
  return callAction("encryption", "unlockMyFiles", arguments);
}

/** This browser forgets the file password. */
export async function lockMyFiles(): Promise<VaultResult> {
  return callAction("encryption", "lockMyFiles", arguments);
}

export async function changeFilePassword(current: string, next: string, confirm: string): Promise<VaultResult> {
  return callAction("encryption", "changeFilePassword", arguments);
}

/** Switch encryption off: the files are decrypted back in the background. */
export async function disableEncryption(password: string): Promise<VaultResult> {
  return callAction("encryption", "disableEncryption", arguments);
}

export async function revokeVaultGrant(id: string): Promise<VaultResult & { status?: VaultStatus }> {
  return callAction("encryption", "revokeVaultGrant", arguments);
}

export async function revokeAllVaultGrants(): Promise<{ ok: true; count: number }> {
  return callAction("encryption", "revokeAllVaultGrants", arguments);
}

/** The unlock page of a link: a file, a gallery or an album. */
export async function unlockOwnerFiles(target: UnlockTarget, password: string, remember: boolean): Promise<VaultResult> {
  return callAction("encryption", "unlockOwnerFiles", arguments);
}
